#r "System.Reflection"
using System;
using System.Reflection;
using System.Linq;

// Load the assemblies
var agentsDll = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.agents.ai/1.11.0/lib/net8.0/Microsoft.Agents.AI.dll");
var extensionsDll = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.extensions.ai/10.7.0/lib/net8.0/Microsoft.Extensions.AI.dll");

// Find ChatClientAgent
var chatClientAgent = agentsDll.GetType("Microsoft.Agents.AI.ChatClientAgent");
Console.WriteLine("=== ChatClientAgent ===");
Console.WriteLine($"Namespace: {chatClientAgent.Namespace}");
Console.WriteLine($"Base Type: {chatClientAgent.BaseType.Name}");

// Constructors
Console.WriteLine("\nConstructors:");
foreach (var ctor in chatClientAgent.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
{
    var parms = string.Join(", ", ctor.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
    Console.WriteLine($"  public ChatClientAgent({parms})");
}

// Key methods
Console.WriteLine("\nKey Methods:");
var methods = new[] { "RunAsync", "RunStreamingAsync", "RunCoreAsync", "RunCoreStreamingAsync" };
foreach (var methodName in methods)
{
    var methodsFound = chatClientAgent.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
        .Where(m => m.Name == methodName);
    foreach (var method in methodsFound)
    {
        var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  {method.ReturnType.Name} {methodName}({parms})");
    }
}

// Find AIAgent base class
var aiAgent = agentsDll.GetType("Microsoft.Agents.AI.AIAgent");
Console.WriteLine("\n=== AIAgent (Base Class) ===");
if (aiAgent != null)
{
    Console.WriteLine($"Namespace: {aiAgent.Namespace}");
    Console.WriteLine($"Is Abstract: {aiAgent.IsAbstract}");

    Console.WriteLine("\nKey Methods:");
    foreach (var methodName in methods)
    {
        var methodsFound = aiAgent.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly)
            .Where(m => m.Name == methodName);
        foreach (var method in methodsFound)
        {
            var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
            Console.WriteLine($"  {method.ReturnType.Name} {methodName}({parms})");
        }
    }
}

// Find ChatClientAgentRunOptions
var runOptions = agentsDll.GetType("Microsoft.Agents.AI.ChatClientAgentRunOptions");
Console.WriteLine("\n=== ChatClientAgentRunOptions ===");
Console.WriteLine($"Namespace: {runOptions.Namespace}");
Console.WriteLine($"Base Type: {runOptions.BaseType.Name}");
Console.WriteLine("\nProperties:");
foreach (var prop in runOptions.GetProperties(BindingFlags.Public | BindingFlags.Instance))
{
    Console.WriteLine($"  {prop.PropertyType.Name} {prop.Name} {{ get; set; }}");
}

// Find AgentRunOptions base
var agentRunOptions = agentsDll.GetType("Microsoft.Agents.AI.AgentRunOptions");
Console.WriteLine("\n=== AgentRunOptions (Base) ===");
if (agentRunOptions != null)
{
    Console.WriteLine($"Namespace: {agentRunOptions.Namespace}");
    Console.WriteLine($"Is Abstract: {agentRunOptions.IsAbstract}");
    Console.WriteLine("\nProperties:");
    foreach (var prop in agentRunOptions.GetProperties(BindingFlags.Public | BindingFlags.Instance))
    {
        Console.WriteLine($"  {prop.PropertyType.Name} {prop.Name} {{ get; {(prop.CanWrite ? "set;" : "")} }}");
    }
}

// Find AIFunction
var aiFunction = extensionsDll.GetType("Microsoft.Extensions.AI.AIFunction");
Console.WriteLine("\n=== AIFunction ===");
if (aiFunction != null)
{
    Console.WriteLine($"Namespace: {aiFunction.Namespace}");
    Console.WriteLine($"Base Type: {aiFunction.BaseType?.Name ?? "N/A"}");
    Console.WriteLine($"Is Abstract: {aiFunction.IsAbstract}");

    Console.WriteLine("\nKey Methods:");
    var invokeMethods = aiFunction.GetMethods(BindingFlags.Public | BindingFlags.Instance)
        .Where(m => m.Name.Contains("Invoke") || m.Name.Contains("Describe"));
    foreach (var method in invokeMethods.Take(5))
    {
        var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  {method.ReturnType.Name} {method.Name}({parms})");
    }
}

// Find AIFunctionFactory
var aiFunctionFactory = extensionsDll.GetType("Microsoft.Extensions.AI.AIFunctionFactory");
Console.WriteLine("\n=== AIFunctionFactory ===");
if (aiFunctionFactory != null)
{
    Console.WriteLine($"Namespace: {aiFunctionFactory.Namespace}");
    Console.WriteLine($"Is Static: {aiFunctionFactory.IsAbstract && aiFunctionFactory.IsSealed}");

    Console.WriteLine("\nKey Static Methods:");
    var staticMethods = aiFunctionFactory.GetMethods(BindingFlags.Public | BindingFlags.Static)
        .Where(m => !m.IsSpecialName);
    foreach (var method in staticMethods.Take(10))
    {
        var parms = string.Join(", ", method.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
        Console.WriteLine($"  static {method.ReturnType.Name} {method.Name}({parms})");
    }
}
