using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tool state (shared notepad) --------------------------------------------
var notes = new List<string>();

// --- Tool definitions --------------------------------------------------------
var searchWebTool = AIFunctionFactory.Create(SearchWebAsync,
    new AIFunctionFactoryOptions
    {
        Name = "search_web",
        Description = "Searches the web for a query and returns relevant results. " +
                      "Use this to gather information about a topic."
    });

var saveNoteTool = AIFunctionFactory.Create(SaveNote,
    new AIFunctionFactoryOptions
    {
        Name = "save_note",
        Description = "Saves a research note. Use this to record key findings, " +
                      "facts, or insights discovered during research."
    });

var readNotesTool = AIFunctionFactory.Create(ReadNotes,
    new AIFunctionFactoryOptions
    {
        Name = "read_notes",
        Description = "Returns all research notes saved so far. " +
                      "Use this to review what you have gathered before writing a summary."
    });

// --- Build the chat client and agent ----------------------------------------
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the search_web tool multiple times with different queries to gather
           diverse information about the topic.
        2. Use save_note to record each key finding as a concise note.
        3. After gathering enough information, use read_notes to review your findings.
        4. Produce a well-structured summary with sections and bullet points.
        Always search at least 2-3 different angles of the topic before summarising.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: [searchWebTool, saveNoteTool, readNotesTool]);

// --- Run the agent ----------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (powered by AI)      ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

string topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptUser();

Console.WriteLine();
Console.WriteLine($"🔍 Researching: {topic}");
Console.WriteLine(new string('─', 50));

var runOptions = new ChatClientAgentRunOptions(
    new ChatOptions { Temperature = 0f, MaxOutputTokens = 2048 });

AgentResponse response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session: null,
    options: runOptions);

Console.WriteLine();
Console.WriteLine("📋 Research Summary");
Console.WriteLine(new string('═', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('═', 50));
Console.WriteLine($"Notes collected: {notes.Count}");

// --- Tool implementations ----------------------------------------------------
[Description("Searches the web for a query and returns relevant results.")]
async Task<string> SearchWebAsync(
    [Description("The search query to look up")] string query)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    // Simulate web search latency
    await Task.Delay(100);

    // In production, replace this with a real search API (e.g. Bing Search).
    // This simulation returns plausible results so the agent loop works end-to-end.
    var results = GenerateSimulatedResults(query);
    return results;
}

[Description("Saves a research note.")]
string SaveNote(
    [Description("The note content to save")] string note)
{
    notes.Add(note);
    Console.WriteLine($"  📝 Note #{notes.Count} saved");
    return $"Note saved (total: {notes.Count}).";
}

[Description("Returns all research notes saved so far.")]
string ReadNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  📖 Reading {notes.Count} note(s)");
    return string.Join("\n",
        notes.Select((n, i) => $"[{i + 1}] {n}"));
}

static string PromptUser()
{
    Console.Write("Enter a topic to research: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input) ? "quantum computing" : input;
}

static string GenerateSimulatedResults(string query)
{
    // Provide deterministic simulated results keyed on common keywords so the
    // agent can demonstrate the full search → note → summarise loop.
    var lowerQuery = query.ToLowerInvariant();

    if (lowerQuery.Contains("quantum"))
        return """
            1. Quantum computing uses qubits that can exist in superposition, enabling
               parallel computation. IBM and Google lead current hardware development.
            2. In 2019 Google claimed "quantum supremacy" with its 53-qubit Sycamore processor.
            3. Key algorithms: Shor's (factoring), Grover's (search), VQE (chemistry).
            4. Current challenges include error correction, decoherence, and extreme cooling
               requirements (near absolute zero).
            5. Market forecast: quantum computing market expected to reach $65B by 2030.
            """;

    if (lowerQuery.Contains("application") || lowerQuery.Contains("use case"))
        return """
            1. Drug discovery: simulating molecular interactions for new pharmaceuticals.
            2. Cryptography: quantum computers threaten RSA; post-quantum crypto is emerging.
            3. Financial modeling: portfolio optimization and risk analysis.
            4. Supply chain: solving complex logistics optimization problems.
            5. Climate modeling: simulating atmospheric systems at molecular level.
            """;

    if (lowerQuery.Contains("history") || lowerQuery.Contains("timeline"))
        return """
            1. 1981: Richard Feynman proposes quantum computing concept.
            2. 1994: Peter Shor develops quantum factoring algorithm.
            3. 1998: First 2-qubit quantum computer demonstrated.
            4. 2019: Google achieves quantum supremacy with 53 qubits.
            5. 2023: IBM unveils 1,121-qubit Condor processor.
            6. 2024-2025: Focus shifts to error-corrected logical qubits.
            """;

    // Fallback for any other query
    return $"""
        1. "{query}" is an active area of research with growing interest.
        2. Recent advances include improved methodologies and broader applications.
        3. Key challenges remain in scalability, cost, and accessibility.
        4. Industry analysts project significant growth over the next decade.
        5. Academic and commercial collaboration is accelerating progress.
        """;
}

